evidence.en:
// Group invoices by customer email
const byCustomer = new Map();
for (const inv of invoices) {
  const key = inv.email;        // "Ana@Example.com " vs "ana@example.com"
  const list = byCustomer.get(key) ?? [];
  list.push(inv);
  byCustomer.set(key, list);
}
// Report: "Ana@Example.com " → $1200, "ana@example.com" → $800
// Same person. Two groups.

